			<defs>
				<pattern id="grid" x="4.1666666667%" width="4.1666666667%" height="100%" patternUnits="objectBoundingBox">
					<line x1="0" y1="0" x2="0" y2="100%" stroke="#898686" stroke-dasharray="1 6"/>
				</pattern>
			</defs>

			<g id="hover-layer" fill="none" stroke="#004fd1" stroke-width="1" stroke-linejoin="round" pointer-events="none"/>
			<script><![CDATA[
				const hoverLayer = document.getElementById("hover-layer");
				document.querySelectorAll("path").forEach(path => {
					path.addEventListener("mouseenter", () => {

						hoverLayer.replaceChildren();

						const clone = path.cloneNode();

						clone.removeAttribute("fill");

						hoverLayer.appendChild(clone);
					});

					path.addEventListener("mouseleave", () => {
						hoverLayer.replaceChildren();
					});
				});
				]]>
			</script>
		</svg>
		{{$after}}
